 mandatory_preconditions=["A rate/price/accrual is fixed for an epoch and read at claim time","A position can be created and claimed within, or straddling, one epoch","No proration by holding time","A funded pool honours the claim"],
 optional_amplifiers=["Flash loans","Predictable settlement timestamp","Re-entrant callbacks inside the epoch","Referral or multiplier logic"],
 applicable_protocol_archetypes=["epoch settlement","lending with daily accrual","yield vault with periodic pricing","structured product","perpetuals funding"],
