 runtime_state_indicators=["stored epoch price stale relative to live market","deposits spiking immediately before settlement","no minimum holding period"],
 cross_contract_indicators=["settlement keeper callable by anyone","epoch price set by an off-chain updater on a fixed cadence"],
 decisive_guards=["Time-weighted entitlement (prorate by seconds held within the epoch)","Minimum holding period or deposit lock across settlement","Deposits after the epoch price is fixed accrue from the next epoch"],
