 mandatory_preconditions=["A signature check gates a value-moving action","The check can return true without a valid signer (ecrecover zero, unchecked return, malformed accepted)","The gated action moves value or grants approval","Reachable by an unprivileged caller"],
 optional_amplifiers=["Admin/signer address set to zero","Wrapper tokens holding many users' assets","Permit-based approval flows"],
 applicable_protocol_archetypes=["reward distributor","wrapper/vault token","NFT staking","payments","any permit-enabled token"],
 static_indicators=["ecrecover used without a require(signer != address(0))","permit implementations diverging from the EIP-2612 reference","verification result compared to a mutable address that may be zero"],
 adapter_indicators=["adapter lists wrapper tokens with custom permit implementations"],
 runtime_state_indicators=["admin/signer variable reading address(0)","wrapper tokens with many holders and live balances"],
 cross_contract_indicators=["one wrapper's permit governs assets held in another contract"],
 decisive_guards=["require(recovered != address(0) && recovered == expected)","Use of ECDSA.recover (OZ) which reverts on invalid signatures","Signer address immutable or non-zero-enforced at the setter"],
 false_positive_killers=["OZ ECDSA library in the deployed bytecode (kills the ecrecover-zero shape)","Signer address immutable and non-zero"],
